const b = $input.item.json;

const colors = (b.primary_colors || []).join(', ') || 'not specified';
const accents = (b.accent_colors || []).join(', ') || 'not specified';
const tones  = (b.tone_keywords  || []).join(', ') || 'modern';
const fonts  = (b.fonts || []).join(', ') || 'not specified';

const prompt = `You are an expert creative director specializing in brand identity and social media design.

CLIENT BRAND DATA:
- Company: ${b.company_name}
- Tagline: ${b.tagline}
- Description: ${b.description}
- Industry: ${b.industry_hint}
- Tone/Style: ${tones}
- Primary colors: ${colors}
- Accent colors: ${accents}
- Fonts: ${fonts}
- Data source: ${b.scrape_method}

TASK: Generate a Stable Diffusion prompt for a professional 1:1 Instagram post that:
1. Visually represents this brand's identity using the EXACT color palette above
2. Is striking and on-brand with clean composition
3. Leaves ~30% of the image as a clean background area for text overlay
4. Describes ONLY visual elements (no text, logos, or faces)
5. Uses cinematic lighting and professional photography style

Respond with ONLY a valid JSON object, no other text:
{
  "positive_prompt": "...",
  "negative_prompt": "...",
  "style_hint": "...",
  "background_color_suggestion": "#HEXCODE"
}`;

return {
  ollama_body: {
    model: 'llama3',
    stream: false,
    prompt: prompt
  },
  brand_data: b
};

const ollamaResp = $input.item.json;
const brandData  = $('Prepara Prompt Ollama').item.json.brand_data;

const raw = ollamaResp.response || ollamaResp.message?.content || '';

let promptData = null;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) promptData = JSON.parse(match[0]);
} catch(e) { promptData = null; }

if (!promptData || !promptData.positive_prompt) {
  const colorList = (brandData.primary_colors || []).map(c => `hex color ${c}`).join(', ');
  const tones     = (brandData.tone_keywords   || ['modern']).join(', ');
  promptData = {
    positive_prompt: `professional ${tones} brand visual for ${brandData.industry_hint || 'business'}, ${colorList}, abstract geometric shapes, clean minimal background, luxury aesthetic, product photography`,
    negative_prompt: 'text, letters, words, watermark, logo, blurry, ugly, deformed, nsfw, low quality, pixelated, oversaturated',
    style_hint: `${tones} ${brandData.industry_hint || 'professional'}`,
    background_color_suggestion: brandData.primary_colors?.[0] || '#1A1A2E'
  };
}

const colorDesc = (brandData.primary_colors || []).map(c => `hex ${c}`).join(', ');
const toneDesc  = (brandData.tone_keywords   || ['modern']).join(', ');

const positiveEnhanced = [
  promptData.positive_prompt,
  colorDesc,
  `${toneDesc} aesthetic`,
  'professional photography, cinematic lighting, high quality, sharp focus, 8k uhd'
].filter(Boolean).join(', ');

return {
  positive_prompt: positiveEnhanced,
  negative_prompt: promptData.negative_prompt || 'text, watermark, blurry, deformed, ugly, low quality',
  style_hint: promptData.style_hint,
  bg_color: promptData.background_color_suggestion || brandData.primary_colors?.[0] || '#1A1A2E',
  brand_data: brandData
};

const data  = $input.item.json;
const brand = data.brand_data;

const slug = (brand.company_name || 'brand')
  .replace(/[^a-zA-Z0-9]/g, '_')
  .substring(0, 20);
const ts = Date.now();
const filenamePrefix = `brand_${slug}_${ts}`;

// ── CAMBIA QUESTO con il modello che hai in ComfyUI/models/checkpoints/ ──
const MODEL = 'dreamshaperXL_v21TurboDPMSDE.safetensors';
// Opzioni comuni:
//   'sd_xl_base_1.0.safetensors'       (SDXL, migliore qualità, 8GB+ VRAM)
//   'v1-5-pruned-emaonly.ckpt'         (SD 1.5, veloce, 4GB VRAM)
//   'dreamshaper_8.safetensors'        (SD 1.5 fine-tuned, ottimo per social)

const workflow = {
  '1': {
    class_type: 'CheckpointLoaderSimple',
    inputs: { ckpt_name: MODEL }
  },
  '2': {
    class_type: 'CLIPTextEncode',
    inputs: { text: data.positive_prompt, clip: ['1', 1] }
  },
  '3': {
    class_type: 'CLIPTextEncode',
    inputs: { text: data.negative_prompt, clip: ['1', 1] }
  },
  '4': {
    class_type: 'EmptyLatentImage',
    inputs: { width: 1024, height: 1024, batch_size: 1 }
  },
  '5': {
    class_type: 'KSampler',
    inputs: {
      seed: Math.floor(Math.random() * 999999999),
      steps: 25,
      cfg: 7.5,
      sampler_name: 'euler_ancestral',
      scheduler: 'karras',
      denoise: 1.0,
      model:        ['1', 0],
      positive:     ['2', 0],
      negative:     ['3', 0],
      latent_image: ['4', 0]
    }
  },
  '6': {
    class_type: 'VAEDecode',
    inputs: { samples: ['5', 0], vae: ['1', 2] }
  },
  '7': {
    class_type: 'SaveImage',
    inputs: { images: ['6', 0], filename_prefix: filenamePrefix }
  }
};

return {
  comfyui_payload: JSON.stringify({ prompt: workflow }),
  filename_prefix: filenamePrefix,
  positive_prompt: data.positive_prompt,
  negative_prompt: data.negative_prompt,
  brand_data: brand,
  style_hint: data.style_hint,
  bg_color: data.bg_color,
  timestamp: ts
};

const promptId    = $('ComfyUI - Invia Job').item.json.prompt_id;
const historyData = $input.item.json;

const jobData = historyData[promptId];
if (!jobData) {
  throw new Error(
    `Timeout: job ${promptId} non completato in 35s. ` +
    'Aumenta i tempi di attesa o controlla ComfyUI.'
  );
}

let imageInfo = null;
for (const nodeId of Object.keys(jobData.outputs || {})) {
  const imgs = jobData.outputs[nodeId]?.images;
  if (imgs && imgs.length > 0) { imageInfo = imgs[0]; break; }
}
if (!imageInfo) throw new Error('Nessuna immagine trovata negli output ComfyUI');

const { filename, subfolder = '' } = imageInfo;
const imageUrl  = `http://host.docker.internal:8188/view?filename=${encodeURIComponent(filename)}&subfolder=${subfolder}&type=output`;
const localPath = `/data/brand-output/${filename}`;

const brand          = $('Prepara Prompt Ollama').item.json.brand_data;
const positivePrompt = $('Parse Risposta Ollama').item.json.positive_prompt;
const buildData      = $('Costruisci Payload ComfyUI').item.json;

return {
  image_filename: filename,
  image_subfolder: subfolder,
  image_url: imageUrl,
  local_path: localPath,
  prompt_id: promptId,
  response_payload: {
    success: true,
    company: brand.company_name,
    industry: brand.industry_hint,
    scrape_method: brand.scrape_method,
    primary_colors: brand.primary_colors,
    accent_colors: brand.accent_colors,
    image_url: imageUrl,
    image_filename: filename,
    saved_to: localPath,
    prompt_used: positivePrompt.substring(0, 300),
    style_hint: buildData.style_hint,
    bg_color: buildData.bg_color,
    prompt_id: promptId,
    generated_at: new Date().toISOString()
  }
};
